private open class PackApiPigeonCodec : StandardMessageCodec() {
  override fun readValueOfType(type: Byte, buffer: ByteBuffer): Any? {
    return when (type) {
      129.toByte() -> {
        return (readValue(buffer) as? List<Any?>)?.let {
          PackInfo.fromList(it)
        }
      }
      130.toByte() -> {
        return (readValue(buffer) as? List<Any?>)?.let {
          BundleInfo.fromList(it)
        }
      }
      131.toByte() -> {
        return (readValue(buffer) as? List<Any?>)?.let {
          PackProgress.fromList(it)
        }
      }
      132.toByte() -> {
        return (readValue(buffer) as? List<Any?>)?.let {
          PackResult.fromList(it)
        }
      }
      133.toByte() -> {
        return (readValue(buffer) as? List<Any?>)?.let {
          PackFeature.fromList(it)
        }
      }
      134.toByte() -> {
        return (readValue(buffer) as? List<Any?>)?.let {
          PackCoverage.fromList(it)
        }
      }
      else -> super.readValueOfType(type, buffer)
    }
  }
  override fun writeValue(stream: ByteArrayOutputStream, value: Any?)   {
    when (value) {
      is PackInfo -> {
        stream.write(129)
        writeValue(stream, value.toList())
      }
      is BundleInfo -> {
        stream.write(130)
        writeValue(stream, value.toList())
      }
      is PackProgress -> {
        stream.write(131)
        writeValue(stream, value.toList())
      }
      is PackResult -> {
        stream.write(132)
        writeValue(stream, value.toList())
      }
      is PackFeature -> {
        stream.write(133)
        writeValue(stream, value.toList())
      }
      is PackCoverage -> {
        stream.write(134)
        writeValue(stream, value.toList())
      }
      else -> super.writeValue(stream, value)
    }
  }
}


/** Generated interface from Pigeon that represents a handler of messages from Flutter. */
interface PackHostApi {
  /**
   * Everything the catalogue knows, merged with what is on disk.
   *
   * Reads the CACHED index only. It never touches the network, so the
   * storefront opens instantly and works on a plane. [refreshCatalogue] is the
   * explicit network call.
   */
  fun catalogue(callback: (Result<List<PackInfo>>) -> Unit)
  /** The bundles, with ownership already resolved. */
